// One-bit sequential circuit. The output p is the function of the input a
// and the previous state, while q is the function of the input a and the
// previous state of p.
module TopModule(input clock, input a, output reg p, output reg q);
  always @(posedge clock) begin
    p <= a ^ p;
    q <= a ^ p;
  end
endmodule

