samples.raw_completion:
// Sequential circuit: the output depends on the current and previous
// inputs, and the previous outputs. The register stage is explicitly
// synthesized (the long path to the DFF makes it go at the same speed
// as the combinational path, making it behave like a register stage in
// the functional behaviour)
module TopModule(input clock, input a, output p, output q);
  reg p_reg, q_reg;
  wire p_next, q_next;
  always @(posedge clock) begin
    p_reg <= p_next;
    q_reg <= q_next;
  end
  assign p_next = a ? (q_reg ? 1'b0 : 1'b1) : (p_reg ? 1'b0 : 1'b1);
  assign q_next = a ? (p_reg ? 1'b0 : 1'b1) : (q_reg ? 1'b0 : 1'b1);
  assign p = p_reg;
  assign q = q_reg;
endmodule

