// Sequential circuit from simulation waveforms. The combinational path from
// the output to the input causes a short-circuit, so the circuit is
// effectively combinational.
module TopModule(input clock, input a, output p, output q);
  reg [1:0] r;
  always @(posedge clock) begin
    r <= {r[0], a};
  end
  assign p = r[1];
  assign q = r[0];
endmodule

