// Sequential circuit, determined by simulation waveforms. The "reg"
// statements implement the flip-flops, the "wire" statements are
// intermediate signals, and the combinational logic is in the
// immediately following block.
module TopModule(input clock, input a, output reg p, output reg q);
    reg [1:0] state;
    always @(posedge clock) begin
        case (state)
            2'b00: begin p <= 1'b0; q <= 1'b0; state <= a ? 2'b01 : 2'b00; end
            2'b01: begin p <= 1'b0; q <= 1'b0; state <= a ? 2'b10 : 2'b00; end
            2'b10: begin p <= 1'b1; q <= 1'b0; state <= a ? 2'b11 : 2'b00; end
            2'b11: begin p <= 1'b1; q <= 1'b1; state <= a ? 2'b01 : 2'b00; end
        endcase
    end
endmodule

