// One-bit sequential circuit, determined by the simulation waveforms. The
// circuit is a combination of DFFs and AND gates, with the AND gates
// forming the long-term functionality of the circuit (the "feedback" path).
module TopModule(
    input  clock,
    input  a,
    output p,
    output q
);
    wire g1, g2, g3, g4;
    reg  r1, r2, r3, r4;
    assign g1 = a & r1;
    assign g2 = a & r2;
    assign g3 = a & r3;
    assign g4 = a & r4;
    always @(posedge clock) begin
        r1 <= g1;
        r2 <= g2;
        r3 <= g3;
        r4 <= g4;
    end
    assign p = r1;
    assign q = r4;
endmodule

