// Sequential circuit with exactly the same behaviour as the reference
// waveform. The name "Seq" is a somewhat arbitrary choice of name for
// the module implementing the circuit.
module Seq(input clock, input a, output reg p, output reg q);
  reg [1:0] state;
  always @(posedge clock) begin
    case (state)
      2'b00: begin p <= 1'b0; q <= 1'b0; state <= a ? 2'b01 : 2'b00; end
      2'b01: begin p <= 1'b0; q <= 1'b0; state <= a ? 2'b10 : 2'b00; end
      2'b10: begin p <= 1'b1; q <= 1'b0; state <= a ? 2'b11 : 2'b00; end
      2'b11: begin p <= 1'b1; q <= 1'b1; state <= a ? 2'b00 : 2'b00; end
    endcase
  end
endmodule

// One-bit sequential circuit: register (p AND NOT(q)) followed by
// register (q AND NOT(p))
module TopModule(input clock, input a, output p, output q);
    reg r1, r2;
    always @(posedge clock) begin
        r1 <= a & ~q;
        r2 <= q & ~r1;
    end
    assign p = r1;
    assign q = r2;
endmodule

